351	    private static boolean isBlank(String value) {
352	        return value == null || value.trim().isEmpty();
353	    }
354	
355	    /**
356	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
357	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
358	     * compared case-insensitively with collapsed whitespace.
359	     */
360	    private static String collapse(String value) {
361	        if (value == null) {
362	            return "";
363	        }
364	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
365	    }
366	
367	    /**
368	     * Common street-type abbreviations expanded during address normalization.
369	     */
370	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
371	        "ST", "STREET",
372	        "RD", "ROAD",
373	        "AVE", "AVENUE");
374	
375	    /**
376	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
377	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
378	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
379	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
380	     * address maps to itself.
381	     */
382	    private static String normalizeAddress(String value) {
383	        if (value == null) {
384	            return "";
385	        }
386	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
387	        if (collapsed.isEmpty()) {
388	            return "";
389	        }
390	        String[] tokens = collapsed.split(" ");
391	        StringBuilder sb = new StringBuilder(collapsed.length());
392	        for (int i = 0; i < tokens.length; i++) {
393	            if (i > 0) {
394	                sb.append(' ');
395	            }
396	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
397	        }
398	        return sb.toString();
399	    }
400	
401	    /**
402	     * Derive the stable household identifier shared by owners with the same normalized last name
403	     * and address. It is a deterministic function of those two values, so every member of a
404	     * household independently derives the same identifier: the first 12 upper-case hex characters
405	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
406	     */
407	    private static String householdId(String normalizedLastName, String normalizedAddress) {
408	        try {
409	            byte[] digest = MessageDigest.getInstance("SHA-256")
410	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
411	            StringBuilder sb = new StringBuilder(digest.length * 2);
412	            for (byte b : digest) {
413	                sb.append(String.format("%02x", b));
414	            }
415	            return sb.substring(0, 12).toUpperCase();
416	        }
417	        catch (NoSuchAlgorithmException e) {
418	            throw new IllegalStateException("SHA-256 not available", e);
419	        }
420	    }
421	
422	    /**
423	     * Build the customer code for a new owner: {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
424	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
425	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the
426	     * number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
427	     */
428	    /**
429	     * Count the existing owners that share the given first and last name, compared
430	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
431	     * namesakes that already existed at creation time (the new owner itself is not included).
432	     */
433	    private int countNamesakes(String firstName, String lastName) {
434	        return (int) this.clinicService.findAllOwners().stream()
435	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
436	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
437	                && existing.getLastName().equalsIgnoreCase(lastName))
438	            .count();
439	    }
440	
441	    /**
442	     * Count the existing owners that already belong to the given household (i.e. carry the same
443	     * non-null householdId). Called after any existing members have been backfilled with the shared
444	     * identifier but before the new owner is saved, so the returned value reflects the members that
445	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
446	     * new owner is not part of any household ({@code householdId} is null).
447	     */
448	    private int countHouseholdMembers(String householdId) {
449	        if (householdId == null) {
450	            return 0;
451	        }
452	        return (int) this.clinicService.findAllOwners().stream()
453	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
454	            .count();
455	    }
456	
457	    /**
458	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
459	     * request to create another owner in it is rejected as a conflict.
460	     */
461	    private static final int MAX_OWNERS_PER_CITY = 50;
462	
463	    /**
464	     * Count the existing owners registered in the given city, compared case-insensitively (as in
465	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
466	     * reflects the owners that already existed at creation time.
467	     */
468	    private int countOwnersInCity(String city) {
469	        return (int) this.clinicService.findAllOwners().stream()
470	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
471	            .count();
472	    }
473	
474	    /**
475	     * The maximum number of owners that may be created on a single day. Once this many owners
476	     * already carry a given day's registration date, a request to create another owner that day is
477	     * rejected with a 429.
478	     */
479	    private static final int MAX_OWNERS_PER_DAY = 100;
480	
481	    /**
482	     * The number of owners that may be created on a single day before the bulk-signup warning is
483	     * flagged. Once more than this many owners already carry a given day's registration date, a
484	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
485	     */
486	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
487	
488	    /**
489	     * Count the existing owners whose registration date is the given day. Called before the new
490	     * owner is saved, so the returned value reflects the owners that already existed at creation
491	     * time.
492	     */
493	    private int countOwnersRegisteredOn(LocalDate date) {
494	        return (int) this.clinicService.findAllOwners().stream()
495	            .filter(existing -> date.equals(existing.getRegistrationDate()))
496	            .count();
497	    }
498	
499	    /**
500	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
501	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
502	     * supplied or defaulted) always falls on a business day.
503	     */
504	    private static LocalDate toBusinessDay(LocalDate date) {
505	        return switch (date.getDayOfWeek()) {
506	            case SATURDAY -> date.plusDays(2);
507	            case SUNDAY -> date.plusDays(1);
508	            default -> date;
509	        };
510	    }
511	
512	    private String nextCustomerCode(String city, String lastName) {
513	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
514	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
515	        long sequence = this.clinicService.findAllOwners().stream()
516	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
517	            .count() + 1L;
518	        return String.format("%s-%s-%04d", city3, last3, sequence);
519	    }
520	
521	    /**
522	     * Required national-number length for each E.164 country calling code we validate: a
523	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
524	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
525	     */
526	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
527	        "1", 10,
528	        "61", 9);
529	
530	    /**
531	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
532	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
533	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
534	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
535	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
536	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
537	     * rejected with a 400.
538	     */
539	    private static String toE164(String raw) {
540	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
541	        boolean hasCountryCode = cleaned.startsWith("+");
542	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
543	        if (!digits.matches("\\d+")) {
544	            throw new InvalidOwnerFieldsException(List.of("telephone"));
545	        }
546	        if (!hasCountryCode) {
547	            if (digits.startsWith("0")) {
548	                digits = digits.substring(1);
549	            }
550	            digits = "61" + digits;
551	        }
552	        if (digits.length() < 8 || digits.length() > 15) {
553	            throw new InvalidOwnerFieldsException(List.of("telephone"));
554	        }
555	        // For a recognised country code, the national number (the digits after the code) must be
556	        // exactly the expected length for that country. Match the longest known code so a shorter
557	        // code that is a prefix of another cannot mask it.
558	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
559	            if (digits.length() <= codeLength) {
560	                continue;
561	            }
562	            String countryCode = digits.substring(0, codeLength);
563	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
564	            if (requiredNationalLength != null) {
565	                if (digits.length() - codeLength != requiredNationalLength) {
566	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
567	                }
568	                break;
569	            }
570	        }
571	        return "+" + digits;
572	    }
573	
574	    /**
575	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
576	     * and a domain with at least one dot-separated label, none of which contain whitespace or
577	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
578	     */
579	    private static final Pattern EMAIL_PATTERN =
580	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
581	
582	    /**
583	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
584	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
585	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
586	     * 400. A valid address is returned lower-cased.
587	     */
588	    private static String normalizeEmail(String email) {
589	        if (email == null || email.isEmpty()) {
590	            return null;
591	        }
592	        String trimmed = email.trim();
593	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
594	            throw new InvalidOwnerFieldsException(List.of("email"));
595	        }
596	        return trimmed.toLowerCase();
597	    }
598	}
